import { useState } from 'react'
import './App.css'
import { AppShell } from './components/AppShell'
import { FrameDetailPage } from './components/FrameDetailPage'
import { FrameEditorPage } from './components/FrameEditorPage'
import { InventoryPage } from './components/InventoryPage'

type Screen =
  | { name: 'inventory' }
  | { name: 'create' }
  | { name: 'detail'; frameId: string }
  | { name: 'edit'; frameId: string }

function App() {
  const [screen, setScreen] = useState<Screen>({ name: 'inventory' })
  const [successMessage, setSuccessMessage] = useState<string | null>(null)
  const [restoreInventoryFocus, setRestoreInventoryFocus] = useState(false)

  const openScreen = (nextScreen: Screen) => {
    setSuccessMessage(null)
    setRestoreInventoryFocus(true)
    setScreen(nextScreen)
  }

  const saved = (frameId: string, mode: 'create' | 'edit') => {
    setSuccessMessage(`Frame ${frameId} ${mode === 'create' ? 'created' : 'updated'}.`)
    setScreen({ name: 'inventory' })
  }

  const breadcrumbs = screen.name === 'create' ? ['Frames', 'New']
    : screen.name === 'edit' ? ['Frames', 'Edit']
      : screen.name === 'detail' ? ['Frames', screen.frameId] : ['Frames']

  return (
    <AppShell breadcrumbs={breadcrumbs}>
      {screen.name === 'inventory' ? (
        <InventoryPage successMessage={successMessage} focusOnMount={restoreInventoryFocus}
          onNew={() => openScreen({ name: 'create' })}
          onView={(frameId) => openScreen({ name: 'detail', frameId })}
          onEdit={(frameId) => openScreen({ name: 'edit', frameId })} />
      ) : screen.name === 'detail' ? (
        <FrameDetailPage frameId={screen.frameId} onBack={() => setScreen({ name: 'inventory' })} />
      ) : (
        <FrameEditorPage mode={screen.name} frameId={screen.name === 'edit' ? screen.frameId : undefined}
          onCancel={() => setScreen({ name: 'inventory' })} onSuccess={saved} />
      )}
    </AppShell>
  )
}

export default App
import type { ReactNode } from 'react'

export function AppShell({ children, breadcrumbs = ['Frames'] }: { children: ReactNode; breadcrumbs?: string[] }) {
  return (
    <div className="app-shell">
      <div className="brand">
        <span className="brand-mark" aria-hidden="true"><FrameIcon /></span>
        <span className="brand-name">Global Inventory<small>Frames Â· OOH</small></span>
      </div>
      <header className="topbar">
        <span>Inventory</span>
        {breadcrumbs.map((breadcrumb, index) => <span className="breadcrumb-part" key={`${breadcrumb}-${index}`}>
          <span className="breadcrumb-separator" aria-hidden="true">/</span>
          <span className={index === breadcrumbs.length - 1 ? 'breadcrumb-current' : undefined}>{breadcrumb}</span>
        </span>)}
      </header>
      <nav className="rail" aria-label="Primary navigation">
        <div className="rail-label">Inventory</div>
        <div className="nav-item" aria-current="page"><FrameIcon /> Frames</div>
      </nav>
      <main className="content">{children}</main>
    </div>
  )
}

function FrameIcon() {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"
      strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <rect x="3" y="5" width="18" height="14" rx="1" /><path d="M3 9h18" />
    </svg>
  )
}
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import {
  FrameApiError,
  getFrames,
  type FrameFilters as FilterValues,
  type FramePage,
  type GetFramesParams,
} from '../api/frames'
import { FrameFilters } from './FrameFilters'
import { FrameTable } from './FrameTable'
import { Pagination } from './Pagination'

const EMPTY_FILTERS: FilterValues = { status: '', mediaType: '', environment: '', format: '', region: '' }
const INITIAL_REQUEST: ActiveRequest = {
  id: 0,
  params: { ...EMPTY_FILTERS, page: 0, size: 20, q: '' },
}

type ActiveRequest = { id: number; params: GetFramesParams }
type RequestUpdate = (current: GetFramesParams) => GetFramesParams
type Props = {
  successMessage: string | null
  focusOnMount: boolean
  onNew: () => void
  onView: (frameId: string) => void
  onEdit: (frameId: string) => void
}

export function InventoryPage({ successMessage, focusOnMount, onNew, onView, onEdit }: Props) {
  const headingRef = useRef<HTMLHeadingElement>(null)
  const [queryInput, setQueryInput] = useState('')
  const [filters, setFilters] = useState<FilterValues>(EMPTY_FILTERS)
  const requestSequence = useRef(0)
  const requestRef = useRef<ActiveRequest>(INITIAL_REQUEST)
  const activeRequestId = useRef(INITIAL_REQUEST.id)
  const [request, setRequest] = useState<ActiveRequest>(INITIAL_REQUEST)
  const [settledRequestId, setSettledRequestId] = useState<number | null>(null)
  const [result, setResult] = useState<FramePage | null>(null)
  const [error, setError] = useState<string | null>(null)
  const loading = settledRequestId !== request.id
  const visibleError = settledRequestId === request.id ? error : null

  useEffect(() => {
    if (focusOnMount) headingRef.current?.focus()
  }, [focusOnMount])
  const filterSuggestions = useMemo(() => {
    const frames = result?.items ?? []
    return {
      mediaType: uniqueValues(frames.map((frame) => frame.mediaType)),
      environment: uniqueValues(frames.map((frame) => frame.environment)),
      format: uniqueValues(frames.map((frame) => frame.format)),
      region: uniqueValues(frames.map((frame) => frame.region)),
    }
  }, [result])

  const scheduleRequest = useCallback((update: RequestUpdate, force = false) => {
    const current = requestRef.current
    const params = update(current.params)
    if (!force && params === current.params) return

    const next = { id: ++requestSequence.current, params }
    requestRef.current = next
    activeRequestId.current = next.id
    setRequest(next)
  }, [])

  useEffect(() => {
    const timeout = window.setTimeout(() => {
      const q = queryInput.trim()

      scheduleRequest((current) => {
        return current.q === q ? current : { ...current, q, page: 0 }
      })
    }, 300)
    return () => window.clearTimeout(timeout)
  }, [queryInput, scheduleRequest])

  useEffect(() => {
    const controller = new AbortController()
    getFrames(request.params, controller.signal)
      .then((data) => {
        if (activeRequestId.current !== request.id) return
        if (request.params.page > 0 && request.params.page >= data.totalPages) {
          const correctedPage = Math.max(0, data.totalPages - 1)
          scheduleRequest((current) => ({ ...current, page: correctedPage }))
          return
        }
        setResult(data)
        setError(null)
        setSettledRequestId(request.id)
      })
      .catch((caught: unknown) => {
        if (caught instanceof DOMException && caught.name === 'AbortError') return
        if (activeRequestId.current !== request.id) return
        setError(caught instanceof FrameApiError || caught instanceof Error ? caught.message : 'An unexpected error occurred.')
        setSettledRequestId(request.id)
      })
    return () => controller.abort()
  }, [request, scheduleRequest])

  const hasActiveFilters = Boolean(
    request.params.q || request.params.status || request.params.mediaType || request.params.environment ||
    request.params.format || request.params.region,
  )
  const changeFilter = <K extends keyof FilterValues,>(name: K, value: FilterValues[K]) => {
    setFilters((current) => ({ ...current, [name]: value }))
    if (name === 'status') {
      const status = value as FilterValues['status']
      scheduleRequest((current) => current.status === status ? current : { ...current, status, page: 0 })
      return
    }

    const suggestionName = name as Exclude<keyof FilterValues, 'status'>
    const normalizedValue = value.trim()
    if (normalizedValue && !filterSuggestions[suggestionName].includes(normalizedValue)) return

    scheduleRequest((current) => current[suggestionName] === normalizedValue
      ? current
      : { ...current, [suggestionName]: normalizedValue, page: 0 })
  }
  const clearFilters = () => {
    setQueryInput('')
    setFilters(EMPTY_FILTERS)
    scheduleRequest((current) => {
      const unchanged = current.q === '' && current.status === '' && current.mediaType === '' &&
        current.environment === '' && current.format === '' && current.region === ''
      return unchanged ? current : { ...current, ...EMPTY_FILTERS, q: '', page: 0 }
    })
  }
  const changeSize = (nextSize: number) => {
    scheduleRequest((current) => current.size === nextSize ? current : { ...current, size: nextSize, page: 0 })
  }
  const changePage = (nextPage: number) => {
    scheduleRequest((current) => current.page === nextPage ? current : { ...current, page: nextPage })
  }
  const retry = () => {
    scheduleRequest((current) => current, true)
  }

  return (
    <>
      <header className="page-header"><div>
          <h1 ref={headingRef} tabIndex={-1}>Frames</h1>
          <p className="page-meta">{result && !visibleError ? `${result.totalElements.toLocaleString()} frames` : 'Search the frame inventory'}</p>
        </div>
        <button className="button button-primary" type="button" onClick={onNew}><PlusIcon /> New frame</button>
      </header>
      {successMessage && <div className="success-message" role="status"><CheckIcon /> {successMessage}</div>}
      <div className="inventory-layout">
        <FrameFilters query={queryInput} filters={filters} suggestions={filterSuggestions} onQueryChange={setQueryInput}
          onFilterChange={changeFilter} onClear={clearFilters} />
        <section className="results" aria-label="Frame results" aria-busy={loading}>
          <div className="surface">
            {loading && (!result || result.items.length === 0) ? <LoadingState /> : visibleError ? (
              <ErrorState message={visibleError} onRetry={retry} />
            ) : result && result.items.length === 0 ? (
              <EmptyState hasActiveFilters={hasActiveFilters} onClear={clearFilters} />
            ) : result ? <>
              {loading && <div className="results-loading" role="status">
                <span className="loading-spinner loading-spinner-small" /> Updating frames
              </div>}
              <FrameTable frames={result.items} onView={onView} onEdit={onEdit} />
              <Pagination page={result.page} size={result.size} totalElements={result.totalElements}
                totalPages={result.totalPages} disabled={loading} onPageChange={changePage} onSizeChange={changeSize} />
            </> : null}
          </div>
        </section>
      </div>
    </>
  )
}

function uniqueValues(values: Array<string | null>) {
  return [...new Set(values.flatMap((value) => value?.trim() ? [value.trim()] : []))]
    .sort((left, right) => left.localeCompare(right))
}

function LoadingState() {
  return <div className="state-panel" role="status"><div className="state-panel-content">
    <span className="state-icon"><span className="loading-spinner" /></span><h2>Loading frames</h2>
    <p>Fetching the latest inventory.</p>
  </div></div>
}

function ErrorState({ message, onRetry }: { message: string; onRetry: () => void }) {
  return <div className="state-panel" role="alert"><div className="state-panel-content">
    <span className="state-icon"><AlertIcon /></span><h2>Could not load frames</h2><p>{message}</p>
    <button className="button button-primary" type="button" onClick={onRetry}>Try again</button>
  </div></div>
}

function EmptyState({ hasActiveFilters, onClear }: { hasActiveFilters: boolean; onClear: () => void }) {
  return <div className="state-panel"><div className="state-panel-content">
    <span className="state-icon"><SearchIcon /></span>
    <h2>{hasActiveFilters ? 'No matching frames' : 'No frames found'}</h2>
    <p>{hasActiveFilters ? 'Try changing your search or clearing the filters.' : 'The inventory does not contain any frames yet.'}</p>
    {hasActiveFilters && <button className="button" type="button" onClick={onClear}>Clear filters</button>}
  </div></div>
}

function SearchIcon() {
  return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
    <circle cx="11" cy="11" r="7" /><path d="m20 20-3.5-3.5" />
  </svg>
}

function AlertIcon() {
  return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
    <circle cx="12" cy="12" r="9" /><path d="M12 8v5M12 16h.01" />
  </svg>
}

function PlusIcon() {
  return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
    <path d="M12 5v14M5 12h14" />
  </svg>
}

function CheckIcon() {
  return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
    <path d="m5 12 4 4L19 6" />
  </svg>
}
export type FrameSummary = {
  frameId: string
  mediaType: string
  format: string
  environment: string | null
  status: string
  modifiedDate: string
  address: string | null
  town: string | null
  region: string | null
  station: string | null
  airport: string | null
}

export type LocationDetails = {
  postcode: string
  postcodeArea: string | null
  postcodeDistrict: string | null
  postcodeSector: string | null
  postcodeUnit: string | null
  address: string | null
  region: string
  countryCode: string | null
  town: string
  longitude: number | null
  latitude: number | null
  distanceToClosestSchool: number | null
  rawLocationPoint: string | null
  locationId: string | null
}

export type SiteDetails = {
  siteNumber: string
  inventorySiteNumber: string | null
  panelNumber: string | null
  station: string | null
  airport: string | null
}

export type TechnicalDetails = {
  illuminationTypeId: string | null
  numberOfSlots: number | null
  sizeCode: string | null
  sizeGroupCode: string | null
  aspectRatioCode: string | null
  sizeCategory: string | null
  pixelHeight: number | null
  pixelWidth: number | null
}

export type CommercialDetails = {
  impactWeight: number | null
  productionRateCard: string | null
  legacyProductionRateCard: string | null
  pricingGrade: string | null
  priceEntityId: string | null
  premium: boolean | null
}

export type IntegrationDetails = {
  broadsignDisplayUnitId: string | null
  broadsignFrameId: string | null
  broadsignDomainId: string | null
  linkedFrameIds: string | null
}

export type FrameWritableDetails = {
  mediaType: string
  format: string
  environment: string | null
  status: 'LIVE' | 'INACTIVE'
  statusReason: string | null
  location: LocationDetails
  site: SiteDetails
  technical: TechnicalDetails | null
  commercial: CommercialDetails | null
  integrations: IntegrationDetails | null
}

export type CreateFrameRequest = FrameWritableDetails & { frameId: string }
export type UpdateFrameRequest = FrameWritableDetails

export type Frame = FrameWritableDetails & {
  frameId: string
  createdDate: string
  modifiedDate: string
}

export type FrameHistoryEventType = 'CREATED' | 'IMPORTED' | 'UPDATED'
export type FrameHistorySource = 'MANUAL' | 'CSV_UPLOAD'

export type FrameFieldChange = {
  old: string | null
  new: string | null
}

export type FrameHistoryEntry = {
  eventType: FrameHistoryEventType
  occurredAt: string
  source: FrameHistorySource
  changedFields: Record<string, FrameFieldChange>
}

export type FramePage = {
  items: FrameSummary[]
  page: number
  size: number
  totalElements: number
  totalPages: number
}

export type FrameFilters = {
  status: '' | 'LIVE' | 'INACTIVE'
  mediaType: string
  environment: string
  format: string
  region: string
}

export type GetFramesParams = FrameFilters & { page: number; size: number; q: string }
export type FrameFieldError = { field: string; message: string }
type ProblemDetail = { title?: string; detail?: string; errors?: FrameFieldError[] }

export class FrameApiError extends Error {
  status: number
  fieldErrors: FrameFieldError[]

  constructor(message: string, status: number, fieldErrors: FrameFieldError[] = []) {
    super(message)
    this.name = 'FrameApiError'
    this.status = status
    this.fieldErrors = fieldErrors
  }
}

export async function getFrames(
  params: GetFramesParams,
  signal?: AbortSignal,
): Promise<FramePage> {
  const searchParams = new URLSearchParams({ page: String(params.page), size: String(params.size) })
  addIfPresent(searchParams, 'q', params.q)
  addIfPresent(searchParams, 'status', params.status)
  addIfPresent(searchParams, 'mediaType', params.mediaType)
  addIfPresent(searchParams, 'environment', params.environment)
  addIfPresent(searchParams, 'format', params.format)
  addIfPresent(searchParams, 'region', params.region)

  return request<FramePage>(`/api/frames?${searchParams.toString()}`, { signal })
}

export function getFrame(frameId: string, signal?: AbortSignal): Promise<Frame> {
  return request<Frame>(`/api/frames/${encodeURIComponent(frameId)}`, { signal })
}

export function getFrameHistory(frameId: string, signal?: AbortSignal): Promise<FrameHistoryEntry[]> {
  return request<FrameHistoryEntry[]>(`/api/frames/${encodeURIComponent(frameId)}/history`, { signal })
}

export function createFrame(payload: CreateFrameRequest): Promise<Frame> {
  return request<Frame>('/api/frames', jsonRequest('POST', payload))
}

export function updateFrame(frameId: string, payload: UpdateFrameRequest): Promise<Frame> {
  return request<Frame>(`/api/frames/${encodeURIComponent(frameId)}`, jsonRequest('PUT', payload))
}

function addIfPresent(params: URLSearchParams, key: string, value: string) {
  const normalizedValue = value.trim()
  if (normalizedValue) params.set(key, normalizedValue)
}

function jsonRequest(method: 'POST' | 'PUT', body: CreateFrameRequest | UpdateFrameRequest): RequestInit {
  return {
    method,
    headers: { Accept: 'application/json', 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  }
}

async function request<T>(url: string, init: RequestInit = {}): Promise<T> {
  const response = await fetch(url, {
    ...init,
    headers: init.headers ?? { Accept: 'application/json' },
  })
  if (!response.ok) throw await readApiError(response)
  return (await response.json()) as T
}

async function readApiError(response: Response): Promise<FrameApiError> {
  try {
    const problem = (await response.json()) as ProblemDetail
    return new FrameApiError(
      problem.detail || problem.title || `Request failed with status ${response.status}`,
      response.status,
      Array.isArray(problem.errors) ? problem.errors : [],
    )
  } catch {
    return new FrameApiError(`Request failed with status ${response.status}`, response.status)
  }
}
