.back-button { width: 34px; min-height: 34px; display: grid; flex: 0 0 auto; place-items: center; padding: 0; }
.editor-layout { max-width: 1040px; margin: 0 auto; padding: var(--space-5) var(--space-6) var(--space-8); }
