const script = `
const ws = new WebSocket(process.argv[2]);
let id = 0;
const pending = new Map();
ws.onmessage = event => {
  const message = JSON.parse(event.data);
  if (message.id && pending.has(message.id)) {
    pending.get(message.id)(message);
    pending.delete(message.id);
  }
};
const call = (method, params = {}) => new Promise(resolve => {
  const next = ++id;
  pending.set(next, resolve);
  ws.send(JSON.stringify({ id: next, method, params }));
});
const evaluate = async expression =>
  (await call("Runtime.evaluate", { expression, returnByValue: true, awaitPromise: true })).result.result.value;
const pause = milliseconds => new Promise(resolve => setTimeout(resolve, milliseconds));
ws.onopen = async () => {
  await call("Runtime.enable");
  await evaluate('[...document.querySelectorAll("button")].find(button => button.textContent.includes("Import CSV")).click()');
  await pause(100);
  await evaluate('window.fetch=async()=>new Response(JSON.stringify({totalRows:20,created:1,duplicates:0,failed:19,errors:[{rowNumber:2,frameId:"bad",reason:"invalid"}]}),{status:200,headers:{"Content-Type":"application/json"}})');
  await evaluate('(()=>{const input=document.querySelector("#csv-file");const transfer=new DataTransfer();transfer.items.add(new File(["frame_id\\\\n1"],"focus.csv",{type:"text/csv"}));input.files=transfer.files;input.dispatchEvent(new Event("change",{bubbles:true}));return true})()');
  await pause(50);
  await evaluate('document.querySelector("form").requestSubmit()');
  await pause(200);
  const inspect = '(()=>{const element=document.activeElement;const style=getComputedStyle(element);return {tag:element.tagName,id:element.id,text:element.textContent,tabIndex:element.tabIndex,outline:style.outline,boxShadow:style.boxShadow}})()';
  const afterResult = await evaluate(inspect);
  await evaluate('[...document.querySelectorAll("button")].find(button => button.textContent.includes("Choose another file")).click()');
  await pause(100);
  const afterChoose = await evaluate(inspect);
  process.stdout.write(JSON.stringify({ afterResult, afterChoose }, null, 2));
  ws.close();
};
`;
