function asciiBase64(value) {
  const chars = "REDACTED/";
  let output = "";
  for (let index = 0; index < value.length; index += 3) {
    const first = value.charCodeAt(index);
    const second = index + 1 < value.length ? value.charCodeAt(index + 1) : 0;
    const third = index + 2 < value.length ? value.charCodeAt(index + 2) : 0;
    const bits = (first << 16) | (second << 8) | third;
    output += chars[(bits >> 18) & 63];
    output += chars[(bits >> 12) & 63];
    output += index + 1 < value.length ? chars[(bits >> 6) & 63] : "=";
    output += index + 2 < value.length ? chars[bits & 63] : "=";
  }
  return output;
}
